// Educational interpretation of the supplied STE administrative manual. Never a switching order.
export const REFERENCES146={
 scope:'El manual aportado es del STE (Trolebús y Tren Ligero). Se adapta su trazabilidad de atención de fallas; no se presenta como procedimiento de operación del STC.',
 ventilation:{alarm:'Flujo reducido en la refrigeración del banco',equipment:'Filtro y ventilador',hypothesis:'La obstrucción visible justifica revisar el filtro antes de atribuir la falla al motor.',criterion:'Comparar 0.6 m/s inicial con 2.4 m/s final y comprobar el ventilador. Valores del ejercicio, no umbrales de aceptación del fabricante.'},
 control:{alarm:'La lámpara auxiliar no enciende',equipment:'Ramal auxiliar de 24 V CD',hypothesis:'24 V en entrada y 0 V en salida localizan una interrupción en el ramal; por sí solos no demuestran que el fusible sea la única causa.',criterion:'Tras revisar el portafusible y sustituir el cartucho del escenario, recuperar 24 V en salida y encender la lámpara.'},
 battery:{alarm:'Caída de tensión elevada en una conexión',equipment:'Puente auxiliar y carga virtual de 10 A',hypothesis:'120 mV con 10 A equivalen a 12 mΩ en este escenario; compara con igual carga después de recuperar el contacto. No determina capacidad de batería.',criterion:'Comparar 120 mV inicial y 12 mV final con 10 A; aislar y recoger puntas.'},
 diodes:{alarm:'Respuesta anómala del módulo rectificador aislado',equipment:'Diodo de potencia y diodo patrón',hypothesis:'Una caída muy baja en ambos sentidos, frente al patrón que bloquea en inversa, es coherente con el cortocircuito simulado.',criterion:'Comparar directa/inversa antes y después. El repuesto del ejercicio conduce en directa y presenta OL en inversa.'},
 insulation:{alarm:'Diferencia marcada entre dos muestras de aislamiento',equipment:'Muestras aisladas y megóhmetro virtual',hypothesis:'Investigar el ramal B: 18 MΩ frente a 620 MΩ en A. No es un criterio normativo de rechazo ni define una tensión de ensayo.',criterion:'Registrar 60 s simulados por muestra, comparar A/B, investigar condiciones y descargar con las puntas conectadas. No asigna tensión ni límite real de aceptación.'},
 relay:{alarm:'El relé auxiliar no responde a la señal de prueba',equipment:'Bobina y contactos de un relé didáctico',hypothesis:'OL en la bobina indica discontinuidad en este escenario. La comparación posterior incluye bobina y contacto NO.',criterion:'Comprobar 960 Ω en bobina, NO abierto sin señal y 0.2 Ω con señal; retirar la señal al terminar. Lecturas simuladas.'}
};
export const phase146=(state)=>state.done?'Comprobación final':state.step?.choices?'Interpretar evidencia':['replace','clean','cleanL','cleanR','remove','install','open','close'].includes(state.step?.effect)||/loosen|tighten/.test(state.step?.effect||'')?'Intervenir en el banco':'Inspeccionar y medir';
export class SubstationDossier146{
 constructor(ui){this.ui=ui;this.actions=[];this.id=null;const doc=ui.doc;this.node=doc.createElement('details');this.node.className='sr146-dossier';this.node.innerHTML='<summary>Expediente de la intervención <span data-sr146-phase></span></summary><p data-sr146-alarm></p><dl><dt>Equipo</dt><dd data-sr146-equipment></dd><dt>Interpretación</dt><dd data-sr146-hypothesis></dd><dt>Comprobación</dt><dd data-sr146-criterion></dd></dl><h4>Bitácora de la sesión</h4><ol data-sr146-log></ol><button type="button" data-sr146-export>Guardar informe de práctica</button><small data-sr146-scope></small>';ui.panel.append(this.node);this.node.querySelector('[data-sr146-scope]').textContent=REFERENCES146.scope;this.node.querySelector('[data-sr146-export]').addEventListener('click',()=>this.download());}
 reset(){this.id=this.ui.state.id;this.actions=[];this.render();}
 record(step,result){if(!result?.ok||!result.complete)return;this.actions.push({step:step?.text||'Retirar puntas',effect:result.effect,interpretation:!!step?.choices,reading:['reading','source','load','verify','airBefore','airAfter','test','technicalDone','dropBefore148','dropAfter148','zero148','discharge148'].includes(result.effect)?this.ui.state.reading:null});this.render();}
 report(){const s=this.ui.state,c=REFERENCES146[s.id];return {schema:'metro-practica146',mission:s.id,title:s.mission.title,completed:s.done,sourceScope:REFERENCES146.scope,alarm:c.alarm,equipment:c.equipment,criterion:c.criterion,actions:this.actions.map(a=>({...a})),measurements:s.log.map(a=>({...a})),result:s.done?'Comprobación didáctica finalizada':'Práctica en curso'};}
 download(){const blob=new Blob([JSON.stringify(this.report(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=this.ui.doc.createElement('a');a.href=url;a.download='Informe_SR_'+this.ui.state.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 render(){if(!this.node)return;const s=this.ui.state,c=REFERENCES146[s.id];this.node.querySelector('[data-sr146-phase]').textContent=phase146(s);for(const key of ['alarm','equipment','hypothesis','criterion'])this.node.querySelector('[data-sr146-'+key+']').textContent=key==='hypothesis'&&!this.actions.some(a=>a.interpretation)?'Reúne la evidencia del banco y elige una interpretación; después podrás contrastarla aquí.':c[key];const list=this.node.querySelector('[data-sr146-log]');list.innerHTML='';const entries=this.actions.slice(-12);for(const a of entries){const li=this.ui.doc.createElement('li');li.textContent=a.step+(a.reading?' · '+a.reading:'');list.append(li);}if(!entries.length){const li=this.ui.doc.createElement('li');li.textContent='Sin intervenciones registradas.';list.append(li);}this.node.querySelector('[data-sr146-export]').disabled=this.ui.busy||!this.ui.bench;}
}
